import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Maintain Project Documentation","description":"","frontmatter":{"docLocale":"en","counterpart":"/guides/documentation","contentType":"guide","prev":false,"next":{"text":"Publish documentation","link":"/en/getting-started/publish-docs"}},"headers":[],"relativePath":"en/guides/documentation.md","filePath":"en/guides/documentation.md"}'),r={name:"en/guides/documentation.md"};function o(d,e,s,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="maintain-project-documentation" tabindex="-1">Maintain Project Documentation <a class="header-anchor" href="#maintain-project-documentation" aria-label="Permalink to &quot;Maintain Project Documentation&quot;">​</a></h1><p>Goal: deliver runnable learning paths and useful references with Lab Word behavior. The writing pattern follows <a href="https://github.com/CaiZongyuan/axum-saas-template/tree/83f1f71bd166af8b604dd50124abc85242b82177/docs" target="_blank" rel="noreferrer">axum-saas-template</a>as inspected on 2026-10-01; topics and facts come from Lab Word&#39;s current source.</p><h2 id="choose-a-reader-task" tabindex="-1">Choose A Reader Task <a class="header-anchor" href="#choose-a-reader-task" aria-label="Permalink to &quot;Choose A Reader Task&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Content order</th><th>Completion</th></tr></thead><tbody><tr><td>Tutorial</td><td>Goal, prior code, complete change, run, result, failure check, next chapter</td><td>Continue the same Lab code</td></tr><tr><td>Guide</td><td>Goal, prerequisites, source/public interface, complete minimal operation, verification, recovery</td><td>Complete the task independently</td></tr><tr><td>Concept</td><td>Definition, real relationship diagram, minimal example, tradeoffs, limits, practical guide</td><td>Understand when it applies and where it fails</td></tr><tr><td>Reference</td><td>Source, classification, parameters, returns, errors, limits, usage</td><td>Find the current contract</td></tr><tr><td>Overview</td><td>Product scope, current stage, task entries, first result</td><td>Know where to start</td></tr></tbody></table><p>Equipment inspection, GLB import and Lab development define the learning path. Link platform topics when Lab needs them. Historical template tickets, generic SaaS courses and template promotion are outside product documentation.</p><h2 id="write-a-verifiable-path" tabindex="-1">Write A Verifiable Path <a class="header-anchor" href="#write-a-verifiable-path" aria-label="Permalink to &quot;Write A Verifiable Path&quot;">​</a></h2><p>Inspect the public interface and actual source, then write “source location → complete operation → command → result → one failure and recovery.” Specify working directory, dependencies, placeholders and persistent writes. Explain reasons after the first result.</p><p>Distinguish production implementation, isolated previews and plans. Screenshots identify actual versions and simulated identities/data. Footer SHA identifies build source and does not establish execution evidence.</p><h2 id="register-and-validate" tabindex="-1">Register And Validate <a class="header-anchor" href="#register-and-validate" aria-label="Permalink to &quot;Register And Validate&quot;">​</a></h2><p>Create an adjacent <code>.en.md</code> and register one stable id, both titles/sources, route, group and type in <a href="https://github.com/CaiZongyuan/labworld/blob/205ed14afe18da0cdefe105042582c67a5395e7d/docs/site.json" target="_blank" rel="noreferrer">site.json</a>. Sequence chapters through <code>previous</code>/<code>next</code> ids; unrelated pages do not form automatic sequences.</p><p>Markdown is canonical content. Rust/OpenAPI owns API facts and Settings owns configuration. Use <code>&lt;&lt;&lt;</code> for checked complete source instead of duplicating code. Scripts generate <code>apps/docs/.generated</code> and build artifacts. Put site images in <code>apps/docs/public/</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e-docs</span></span></code></pre></div><p>The first two validate sources, locale pairing, generated references and built links. Browser journeys validate language, theme, search and deployment base. Test business HTTP, components and actual 3D rendering separately under the <a href="https://github.com/CaiZongyuan/labworld/blob/205ed14afe18da0cdefe105042582c67a5395e7d/docs/testing/strategy.md" target="_blank" rel="noreferrer">testing strategy</a>.</p><p>Lab Word has not published inherited template learning paths. Cleanup removes unrelated pages while retaining routes for adopted chapters. Future reorganization must preserve actual published Lab links, without importing dangling template navigation.</p><h2 id="maintainer-entries" tabindex="-1">Maintainer Entries <a class="header-anchor" href="#maintainer-entries" aria-label="Permalink to &quot;Maintainer Entries&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/205ed14afe18da0cdefe105042582c67a5395e7d/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a>owns vocabulary; <a href="https://github.com/CaiZongyuan/labworld/blob/205ed14afe18da0cdefe105042582c67a5395e7d/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>records product boundaries. The <a href="https://github.com/CaiZongyuan/labworld/blob/205ed14afe18da0cdefe105042582c67a5395e7d/docs/agents/development-flow.md" target="_blank" rel="noreferrer">development flow</a>and <a href="https://github.com/CaiZongyuan/labworld/blob/205ed14afe18da0cdefe105042582c67a5395e7d/docs/agents/documentation.md" target="_blank" rel="noreferrer">author rules</a>define delivery. The original <a href="https://github.com/CaiZongyuan/labworld/blob/205ed14afe18da0cdefe105042582c67a5395e7d/docs/document-guild.md" target="_blank" rel="noreferrer">documentation philosophy</a>remains a writing reference.</p><p>After validation, follow the <a href="./../getting-started/publish-docs">publishing guide</a>.</p><hr><p>Source version：<code>205ed14afe18</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/205ed14afe18da0cdefe105042582c67a5395e7d/docs/guides/maintain-docs.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,19)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
